// BizCard ortak dogrulama: "Karti Kaydet" ve "Toplanti Talep Et" akislari ayni kurallari kullanir.
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;
const TIME_REGEX = /^([01]\d|2[0-3]):[0-5]\d$/;
const VALID_EVENTS = ["card.save", "meeting.request"];
const VALID_CARD_IDS = ["sercan-balli"];
const item = $input.first().json;
const errors = [];
if (!VALID_EVENTS.includes(item.event)) { errors.push("Gecersiz olay turu: " + item.event); }
if (!VALID_CARD_IDS.includes(item.cardId)) { errors.push("Bilinmeyen kart ID: " + item.cardId); }
if (!item.email || !EMAIL_REGEX.test(item.email)) { errors.push("Gecersiz e-posta formati: " + item.email); }
if (!item.timestamp || isNaN(Date.parse(item.timestamp))) { errors.push("Gecersiz zaman damgasi: " + item.timestamp); }
if (item.event === "meeting.request") {
  if (!DATE_REGEX.test(item.preferredDate || "")) { errors.push("Gecersiz toplanti tarihi: " + item.preferredDate); }
  if (!TIME_REGEX.test(item.preferredTime || "")) { errors.push("Gecersiz toplanti saati: " + item.preferredTime); }
}
return [{ json: { valid: errors.length === 0, reason: errors.join(" | ") } }];
